+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      font-size: 1.08rem;
+      font-weight: 700;
+      margin-bottom: 10px;
+    }
+
+    .help-text {
+      margin: 0 0 14px;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .choices {
+      display: grid;
+      gap: 12px;
+    }
+
+    .choice {
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      padding: 12px 14px;
+      background: rgba(30, 41, 59, 0.72);
+      border: 1px solid rgba(96, 165, 250, 0.12);
+      border-radius: 12px;
+      cursor: pointer;
+      transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
+    }
+
+    .choice:hover,
+    .choice:focus-within {
+      transform: translateY(-1px);
+      border-color: rgba(96, 165, 250, 0.45);
+      background: rgba(37, 99, 235, 0.14);
+    }
+
+    input[type="checkbox"] {
+      width: 18px;
+      height: 18px;
+      accent-color: var(--accent-strong);
+      flex: 0 0 auto;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      font-size: 1rem;
+      font-weight: 700;
+      color: #eff6ff;
+      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+      cursor: pointer;
+      justify-self: start;
+      box-shadow: 0 12px 28px rgba(37, 99, 235, 0.35);
+      transition: transform 0.15s ease, box-shadow 0.15s ease;
+    }
+
+    button:hover,
+    button:focus-visible {
+      transform: translateY(-1px);
+      box-shadow: 0 16px 32px rgba(37, 99, 235, 0.42);
+    }
+
+    .result {
+      min-height: 1.5rem;
+      margin: 4px 0 0;
+      font-weight: 700;
+      color: var(--success);
+    }
+
+    @media (max-width: 640px) {
+      .quiz-shell {
+        padding: 24px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="quiz-shell">
+    <h1>Computer Languages Quiz</h1>
+    <p class="intro">Pick every answer you believe is correct for each question, then submit to see your score.</p>
+
+    <form id="quiz-form">
+      <div class="form-field">
+        <fieldset>
+          <legend>1. Which of these are programming languages commonly used for web development?</legend>
+          <p class="help-text">Select all that apply. More than one answer is correct.</p>
+          <div class="choices">
+            <label class="choice"><input type="checkbox" name="q1" value="JavaScript">JavaScript</label>
+            <label class="choice"><input type="checkbox" name="q1" value="Python">Python</label>
+            <label class="choice"><input type="checkbox" name="q1" value="HTML">HTML</label>
+            <label class="choice"><input type="checkbox" name="q1" value="Ruby">Ruby</label>
+          </div>
+        </fieldset>
+      </div>
+
+      <div class="form-field">
+        <fieldset>
+          <legend>2. Which of these languages are primarily compiled before running?</legend>
+          <div class="choices">
+            <label class="choice"><input type="checkbox" name="q2" value="C++">C++</label>
+            <label class="choice"><input type="checkbox" name="q2" value="Java">Java</label>
+            <label class="choice"><input type="checkbox" name="q2" value="Rust">Rust</label>
+            <label class="choice"><input type="checkbox" name="q2" value="PHP">PHP</label>
+          </div>
+        </fieldset>
+      </div>
+
+      <div class="form-field">
+        <fieldset>
+          <legend>3. Which of these are known as markup or style languages rather than general-purpose programming languages?</legend>
+          <div class="choices">
+            <label class="choice"><input type="checkbox" name="q3" value="CSS">CSS</label>
+            <label class="choice"><input type="checkbox" name="q3" value="SQL">SQL</label>
+            <label class="choice"><input type="checkbox" name="q3" value="HTML">HTML</label>
+            <label class="choice"><input type="checkbox" name="q3" value="Java">Java</label>
+          </div>
+        </fieldset>
+      </div>
+
+      <button type="submit">Submit Quiz</button>
+      <p id="result" class="result" aria-live="polite"></p>
+    </form>
+  </main>
+
+  <script>
+    const quizForm = document.getElementById("quiz-form");
+    const result = document.getElementById("result");
+
+    const answerKey = {
+      q1: ["JavaScript", "Python", "Ruby"],
+      q2: ["C++", "Java", "Rust"],
+      q3: ["CSS", "HTML"]
+    };
+
+    function getSelectedValues(name) {
+      return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`))
+        .map((input) => input.value)
+        .sort();
+    }
+
+    function matchesAnswer(selected, correct) {
+      return selected.length === correct.length &&
+        selected.every((value, index) => value === correct.slice().sort()[index]);
+    }
+
+    quizForm.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      let score = 0;
+
+      Object.entries(answerKey).forEach(([questionName, answers]) => {
+        const selected = getSelectedValues(questionName);
+        if (matchesAnswer(selected, answers)) {
+          score += 1;
+        }
+      });
+
+      result.textContent = `You scored ${score} out of ${Object.keys(answerKey).length}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
