             <label class="choice"><input type="checkbox" name="q2" value="Java">Java</label>
             <label class="choice"><input type="checkbox" name="q2" value="Rust">Rust</label>
             <label class="choice"><input type="checkbox" name="q2" value="PHP">PHP</label>
           </div>
         </fieldset>
       </div>

       <div class="form-field">
         <fieldset>
           <legend>3. Which of these are known as markup or style languages rather than general-purpose programming languages?</legend>
           <div class="choices">
             <label class="choice"><input type="checkbox" name="q3" value="CSS">CSS</label>
             <label class="choice"><input type="checkbox" name="q3" value="SQL">SQL</label>
             <label class="choice"><input type="checkbox" name="q3" value="HTML">HTML</label>
             <label class="choice"><input type="checkbox" name="q3" value="Java">Java</label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit Quiz</button>
       <p id="result" class="result" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const quizForm = document.getElementById("quiz-form");
     const result = document.getElementById("result");

     const answerKey = {
       q1: ["JavaScript", "Python", "Ruby"],
       q2: ["C++", "Java", "Rust"],
       q3: ["CSS", "HTML"]
     };

     function getSelectedValues(name) {
       return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`))
         .map((input) => input.value)
         .sort();
     }

     function matchesAnswer(selected, correct) {
       return selected.length === correct.length &&
         selected.every((value, index) => value === correct.slice().sort()[index]);
     }

     quizForm.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;

       Object.entries(answerKey).forEach(([questionName, answers]) => {
         const selected = getSelectedValues(questionName);
         if (matchesAnswer(selected, answers)) {
           score += 1;
         }
       });

       result.textContent = `You scored ${score} out of ${Object.keys(answerKey).length}.`;
     });
   </script>
 </body>
 </html>

